  const t=s=>messages[s]?.[document.documentElement.lang==='nl'?0:document.documentElement.lang==='de'?1:-1]||s;
  const ui={view:'explore',tab:'summary',compare:[],layerStatus:{},measuring:false,measurePoints:[],ready:false,appearance:'day',streetClosed:false};
  const button=(label,id='',cls='pv-button')=>`<button type="button" ${id?`id="${id}"`:''} class="${cls}">${esc(t(label))}</button>`;
  function readStorage(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
  function writeStorage(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{showToast('Local storage is unavailable. Export your brief to keep it.');return false;}}
  function applyAppearance(choice){ui.appearance=['day','night','sand','system'].includes(choice)?choice:'day';const resolved=ui.appearance==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'night':'day'):ui.appearance;document.body.dataset.appearance=resolved;document.body.classList.toggle('theme-dark',resolved==='night');document.body.classList.toggle('theme-light',resolved!=='night');if($('pv-theme'))$('pv-theme').value=ui.appearance;document.querySelector('meta[name="theme-color"]').content=resolved==='night'?'#0b191c':resolved==='sand'?'#f4efe4':'#f5f4ef';writeStorage('planview-appearance',ui.appearance);}
  function navMarkup(mobile=false){
    const items=mobile?[['explore','Map','map'],['search','Search','search'],['layers','Layers','layers2'],['compare','Compare','grid'],['cases','Cases','file']]:[['explore','Map','map'],['compare','Compare','layers2'],['cases','Cases','file']];
    return items.map(([view,label,ico])=>{const active=view==='explore'?!['compare','cases'].includes(ui.view):view===ui.view;const navLabel=view==='compare'?({de:'Vergleich',nl:'Vergelijking'}[document.documentElement.lang]||'Compare'):view==='search'?({de:'Suchen',nl:'Zoeken'}[document.documentElement.lang]||'Search'):view==='layers'?({de:'Ebenen',nl:'Lagen'}[document.documentElement.lang]||'Layers'):t(label);const tool=['layers','search'].includes(view);return `<button type="button" ${tool?`data-mobile-tool="${view}"`:`data-view="${view}"`} class="${active?'active':''}" aria-pressed="${active}">${icon(ico)}<span>${esc(navLabel)}</span>${view==='compare'?`<span class="pv-nav-count">${ui.compare.length}</span>`:''}</button>`;}).join('');
  }
  function updateNav(){for(const [id,mobile] of [['pv-nav',false],['pv-mobile-nav',true]]){if(!$(id))continue;$(id).innerHTML=navMarkup(mobile);$(id).querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{if(mobile&&b.dataset.view==='explore')window.dispatchEvent(new Event('planview-mobile-map'));setView(b.dataset.view);});$(id).querySelectorAll('[data-mobile-tool]').forEach(b=>b.onclick=()=>$(b.dataset.mobileTool==='layers'?'pv-layers':'pv-research')?.click());}}
  function notifyView(){window.dispatchEvent(new CustomEvent('planview-view-change',{detail:{view:ui.view,inspectorOpen:$('detail-panel')?.classList.contains('open')||false,researchOpen:!!window.planviewAdvanced?.open}}));}
  function setView(view){
    if(!['explore','inspect','search','compare','cases'].includes(view))return;
    if(view!=='compare')window.PlanViewComparison?.deactivate();
    if(view!=='explore'&&ui.measuring)stopMeasure();
    const inspector=$('detail-panel'),research=window.planviewAdvanced;
    const keepInspector=view==='search'&&innerWidth>=1360&&inspector.classList.contains('open');
    const keepResearch=view==='inspect'&&innerWidth>=1360&&research?.open;
    if(!keepInspector)inspector.classList.remove('open');
    $('sidebar').classList.remove('open');$('pv-workbench').hidden=true;
    if(view!=='search'&&!keepResearch)research?.setOpen?.(false);
    ui.view=view;
    document.body.classList.toggle('pv-inspecting',view==='inspect'||keepInspector);
    document.body.classList.toggle('pv-searching',view==='search'||keepResearch);
    if(view==='inspect'){inspector.classList.add('open');if(!state.selected)renderWelcome();}
    if(view==='search')research?.setOpen?.(true);
    if(view==='compare'||view==='cases'){document.body.classList.add('pv-sidebar-hidden');renderWorkbench(view);if(view==='compare')ui.compare.filter(item=>item.enrichmentState!=='loading'&&(!item.enrichmentAt||Date.now()-Date.parse(item.enrichmentAt)>600000)).forEach(enrichCompare);}
    else if(innerWidth>1200)document.body.classList.remove('pv-sidebar-hidden');
    updateNav();notifyView();
  }
  function closeInspector(){const researchOpen=window.planviewAdvanced?.open;$('detail-panel').classList.remove('open');setView(researchOpen?'search':'explore');$(researchOpen?`research-tab-${window.planviewAdvanced.activeTab||'results'}`:'search')?.focus({preventScroll:true});}
  function addShell(){
    const nav=document.createElement('nav');nav.id='pv-nav';nav.className='pv-nav';nav.setAttribute('aria-label','Workspace');nav.dataset.pvManaged='';document.querySelector('.brand').after(nav);
    $('theme-toggle').hidden=true;const theme=document.createElement('select');theme.id='pv-theme';theme.className='pv-theme';theme.dataset.pvManaged='';theme.setAttribute('aria-label',t('Appearance'));theme.innerHTML=['day','night','sand','system'].map(v=>`<option value="${v}">${t(v[0].toUpperCase()+v.slice(1))}</option>`).join('');$('theme-toggle').before(theme);theme.onchange=()=>applyAppearance(theme.value);
    const presets=document.createElement('div');presets.className='pv-presets';presets.id='pv-presets';presets.dataset.pvManaged='';presets.innerHTML=button('Planning','pv-planning')+button('Context','pv-context');document.querySelector('.select-wrap').after(presets);
    $('pv-planning').onclick=()=>preset('planning');$('pv-context').onclick=()=>preset('context');
    const toolbar=document.createElement('div');toolbar.id='pv-toolbar';toolbar.className='pv-toolbar';toolbar.dataset.pvManaged='';toolbar.innerHTML=`<button id="pv-layers" type="button">${icon('layers')}<span>${t('Layers')}</span></button><button id="pv-draw" type="button">${icon('square')}<span>${t('Draw area')}</span></button><button id="pv-measure" type="button">${icon('ruler')}<span>${t('Measure')}</span></button>`;document.querySelector('.map-stage').append(toolbar);
    $('pv-layers').onclick=()=>{if(innerWidth<=600){$('sidebar').classList.toggle('open');$('detail-panel').classList.remove('open');document.body.classList.remove('pv-inspecting');window.planviewAdvanced?.setOpen(false);}else{document.body.classList.toggle('pv-sidebar-hidden');if(innerWidth<=1200&&$('detail-panel').classList.contains('open'))setView('explore');}};
    $('pv-draw').onclick=async()=>{if(state.perspective){showToast(t('Switching to 2D to mark an area.'));await togglePerspective();if(state.perspective)return;}$('pv-welcome').hidden=true;stopMeasure();setView('explore');window.planviewAdvanced?.startDrawing(false);};$('pv-measure').onclick=()=>ui.measuring?stopMeasure():startMeasure();
    const welcome=document.createElement('section');welcome.hidden=true;welcome.className='pv-welcome';welcome.id='pv-welcome';welcome.dataset.pvManaged='';welcome.innerHTML=`<div class="eyebrow">LIMBURG / 31</div><h2>${t('Your next site starts here.')}</h2><p>${t('Explore adjoining plans, then click a location to inspect its source.')}</p>${button('Explore Maastricht','pv-example','pv-button primary')}`;document.querySelector('.map-stage').append(welcome);$('pv-example').onclick=()=>{selectMunicipality('0935');navigateToPoint(FOCUS,17);selectPoint(FOCUS);};
    const street=document.createElement('section');ui.street=street;street.id='pv-street';street.className='pv-street';street.hidden=true;street.dataset.pvManaged='';street.setAttribute('aria-label',t('Location context'));street.innerHTML=`<div class="pv-preview-image"><div class="pv-aerial" id="pv-aerial" aria-label="${esc(t('Aerial image · Esri'))}"></div><span class="pv-preview-credit">${esc(t('Aerial image · Esri'))}</span><div id="pv-preview-status" class="pv-preview-status pv-loading" role="status"></div></div><div class="pv-street-copy"><div class="pv-preview-head"><strong>${t('Location context')}</strong><span id="pv-preview-coordinates"></span></div><a class="pv-preview-primary" id="pv-street-link" target="_blank" rel="noopener noreferrer">${icon('external')} <span>${t('Google Street View')}</span></a><div class="pv-preview-links"><a id="pv-maps-link" target="_blank" rel="noopener noreferrer">Google Maps ${icon('external')}</a></div><p class="pv-preview-note">${t('Imagery availability and date can be checked in Google Maps.')}</p></div>`;document.querySelector('.map-stage').append(street);
    const workbench=document.createElement('section');workbench.id='pv-workbench';workbench.className='pv-workbench';workbench.dataset.pvManaged='';workbench.hidden=true;workbench.setAttribute('aria-label','Comparison and saved cases');document.querySelector('.workspace').append(workbench);
    const mobile=document.createElement('nav');mobile.id='pv-mobile-nav';mobile.className='pv-mobile-nav';mobile.dataset.pvManaged='';mobile.setAttribute('aria-label','Mobile workspace');document.querySelector('.workspace').append(mobile);
    const zoom=document.createElement('button');zoom.id='pv-zoom-detail';zoom.className='pv-zoom-detail';zoom.dataset.pvManaged='';zoom.textContent=t('Zoom to detail');$('layer-list').after(zoom);zoom.onclick=()=>{const map=state.perspective?state.perspectiveMap:state.map;const p=state.perspective?{lat:map.getCenter().lat,lng:map.getCenter().lng}:map.getCenter();navigateToPoint(p,17);};
    updateNav();
  }
  function preset(name){for(const d of layerDefs){d.on=(name==='planning'?['zoning','double','building','function','area','dso','parcels']:['parcels','novex','provincial','projects','camping']).includes(d.id);}document.querySelectorAll('[data-layer]').forEach(el=>el.checked=layerDefs.find(d=>d.id===el.dataset.layer).on);updateLayers();for(const d of layerDefs.filter(d=>d.on&&state.selected?.skippedLayers?.includes(d.id)))loadOverlayForSelection(d,state.selected);$('pv-planning').classList.toggle('active',name==='planning');$('pv-context').classList.toggle('active',name==='context');}
  function layerStates(){if(!ui.ready)return;cancelAnimationFrame(layerStates.frame);layerStates.frame=requestAnimationFrame(refreshLayerStates);}
  function refreshLayerStates(){if(!ui.ready)return;const zoom=state.perspective&&state.perspectiveReady?state.perspectiveMap.getZoom():state.map.getZoom();for(const d of layerDefs){const row=document.querySelector(`[data-layer="${d.id}"]`)?.closest('.layer-row');if(!row)continue;let label=row.querySelector('.pv-layer-state');if(!label){label=document.createElement('small');label.className='pv-layer-state';label.dataset.pvManaged='';row.querySelector('.layer-label').append(label);}if(d.context)continue;const hidden=d.on&&!d.context&&!d.localSource&&!['zoning','novex'].includes(d.id)&&zoom<12;const k=!d.on?'off':hidden?'zoom':ui.layerStatus[d.id]||'visible';label.dataset.state=k;const text=t({off:'Off',zoom:'Visible closer in',loading:'Loading…',error:'Some tiles unavailable',visible:'Visible'}[k]);if(label.textContent!==text)label.textContent=text;}if($('pv-zoom-detail'))$('pv-zoom-detail').hidden=zoom>=16;}
  function relevantFeatures(key,s=state.selected){if(!s?.layers[key])return null;return s.layers[key].filter(f=>{const geo=geoToLatLng(f);return f.properties?.plangebied===s.primary?.properties?.plangebied&&geo&&['Polygon','MultiPolygon'].includes(geo.geometry.type)&&geometryContains(geo.geometry,s.point);});}
